WITH with_windows AS (SELECT id, name, email, country, segment, signup_date, credit_limit, CORR(credit_limit, age) OVER (PARTITION BY country, segment) corr_credit_limit_age, AVG(credit_limit) OVER (ORDER BY age, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) credit_limit_avg_2 FROM customers) SELECT id, name, email, country, segment, signup_date, credit_limit, credit_limit_avg_2, CASE WHEN name RLIKE '^(Grace Kim|Alice Wong)$' THEN 'OTHER_ZONE' WHEN name RLIKE '^(bob smith|  Carol Diaz)$' THEN 'EXTENDED' ELSE 'PRIORITY' END AS name_zone FROM with_windows ORDER BY id, name_zone DESC
